<script setup>
import BulkOperationsPanel from '../components/BulkOperationsPanel.vue';
import InstallmentsEditor from '../components/InstallmentsEditor.vue';
import {focusError,firstField} from '../lib/entry-focus';
import DateInput from '../components/DateInput.vue';
import CfopInput from '../components/CfopInput.vue';
import {ref,computed,onUnmounted,nextTick,watch} from 'vue';import Icon from '../components/Icon.vue';import BaseModal from '../components/BaseModal.vue';import EmptyState from '../components/EmptyState.vue';
import {state,company,api,scope,useResource,rows,notify,ask,changed} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';
import {navigate} from '../lib/workspace';import {money,date,amount,inputMoney,periodDate,uid,normalized,statusLabel} from '../lib/format';
const query=ref(''),direction=ref(''),status=ref(''),show=ref(false),tab=ref('document'),busy=ref(false),error=ref(''),form=ref({}),original=ref(null),context=ref({}),book=ref(false),booking=ref({});let baseline='';
const selectedIds=ref([]),bulkBusy=ref(false);
function toggleSelection(id,checked){if(bulkBusy.value)return;selectedIds.value=checked?[...new Set([...selectedIds.value,id])].slice(0,5000):selectedIds.value.filter(x=>x!==id);}
const taxNames={icms:'ICMS',ipi:'IPI',pis:'PIS',cofins:'Cofins',iss:'ISS',ibs:'IBS',cbs:'CBS'};
const {data,loading,error:loadError}=useResource(async()=>{if(!state.companyId)return {documents:[],accounts:[]};const[d,a,p,e,g,v,m]=await Promise.all([api(scope(`/documents?year=${state.period.slice(0,4)}`)),allowedApi('accounting.accounts',scope('/accounts')),allowedApi('fiscal.masters',scope('/masters/participant')),allowedApi('fiscal.masters',scope('/masters/establishment')),allowedApi('fiscal.masters',scope('/masters/product')),allowedApi('fiscal.masters',scope('/masters/service')),allowedApi('accounting.histories',scope('/masters/accounting_model'))]);return {documents:rows(d),accounts:rows(a),participants:p,establishments:e,products:[...g,...v],models:m};},{documents:[],accounts:[],participants:[],establishments:[],products:[],models:[]});
const filtered=computed(()=>data.value.documents.filter(d=>(!monthFilter.value||d.period.slice(5)===monthFilter.value)&&(!direction.value||d.direction===direction.value)&&(!status.value||d.status===status.value)&&normalized(`${d.number} ${d.partner_name} ${d.key} ${d.cfop}`).includes(normalized(query.value))));
const monthFilter=ref(''),page=ref(1),pageSize=ref(50);
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
watch([query,direction,status,monthFilter,pageSize,()=>state.companyId,()=>state.period,()=>data.value.documents],()=>page.value=1);
const exportUrl=computed(()=>`/api${scope('/movement-exports/documents.xlsx')}?${new URLSearchParams({year:state.period.slice(0,4),month:monthFilter.value,query:query.value,direction:direction.value,status:status.value})}`);
const retain=ref({date:true,classification:true,partner:false});const saveNext=ref(false);
function canEditDocument(d){return writable('fiscal.documents','edit',d.period)&&!(d.status==='booked'&&(d.journal_id||!can('fiscal.documents','book')))}
const locked=computed(()=>original.value?!canEditDocument(original.value):!writable('fiscal.documents','create'));
function open(d=null){original.value=d;context.value={id:state.companyId,name:company.value?.trade_name||company.value?.name,code:company.value?.code,period:state.period};form.value=d?{...d,edit_reason:'',total:inputMoney(d.total_cents),taxes:{...(d.taxes||{})},items:JSON.parse(JSON.stringify(d.items||[]))}:{direction:'incoming',model:'55',number:'',series:'1',issue_date:periodDate(state.period),posting_date:periodDate(state.period),partner_name:'',partner_tax_id:'',key:'',cfop:'',total:'',taxes:{},items:[],idempotency_key:uid()};baseline=JSON.stringify(form.value);tab.value='document';error.value='';show.value=true;state.editor={name:'Documento fiscal',companyId:state.companyId};}
async function close(){if(busy.value)return;if(!locked.value&&baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar edição?',message:'As alterações no documento ainda não foram salvas.',confirmLabel:'Descartar',danger:true}))return;show.value=false;book.value=false;state.editor=null;}
function submitNext(){const form=document.getElementById('document-form');if(form?.reportValidity()){saveNext.value=true;form.requestSubmit()}}
async function save(){if(busy.value)return;const el=document.getElementById('document-form');if(!el.checkValidity()){tab.value='document';await nextTick();el.reportValidity();return;}busy.value=true;error.value='';try{if(!form.value.posting_date.startsWith(context.value.period.slice(0,4)))throw new Error('A escrituração deve pertencer ao exercício selecionado.');const payload={...form.value,total:amount(form.value.total),taxes:Object.fromEntries(Object.entries(form.value.taxes).filter(([,v])=>v!==''&&v!==null).map(([k,v])=>[k,Object.hasOwn(taxNames,k)&&typeof v!=='object'?amount(v):v])),reason:original.value?.status==='booked'?form.value.edit_reason:'Conferência e edição do documento pelo operador'};await api(scope(`/documents${original.value?`/${original.value.id}`:''}`,context.value.id),{method:original.value?'PUT':'POST',body:payload});const previous={...form.value};const another=saveNext.value&&!original.value;saveNext.value=false;if(another){open();if(retain.value.date){form.value.issue_date=previous.issue_date;form.value.posting_date=previous.posting_date;}if(retain.value.classification)for(const k of ['direction','model','series','cfop','establishment_id'])form.value[k]=previous[k];if(retain.value.partner)for(const k of ['participant_id','partner_name','partner_tax_id'])form.value[k]=previous[k];baseline=JSON.stringify(form.value);await nextTick();firstField('document-form');}else{show.value=false;state.editor=null;}changed();notify(original.value?.status==='booked'?'Escrituração atualizada com histórico e origem preservados.':'Documento salvo como pendente de conferência.');}catch(e){error.value=e.message;tab.value='document';saveNext.value=false;await nextTick();focusError('document-form',e.message);}finally{busy.value=false;}}
async function review(d){const reason=await ask({title:'Registrar conferência',message:`Confirme que os dados, a operação e os valores do documento ${d.number} foram revisados. Esta ação não certifica o tratamento tributário.`,inputLabel:'Observação da conferência',required:true,confirmLabel:'Marcar como conferido'});if(!reason)return;try{await api(scope(`/documents/${d.id}/review`),{method:'POST',body:{version:d.version,reason}});changed();notify('Conferência registrada.');}catch(e){notify(e.message,'error');}}
function openBook(d){original.value=d;context.value={id:state.companyId,name:company.value?.trade_name||company.value?.name,period:state.period};booking.value={generate_titles:false,installments:[],model_id:'',integrate:false,debit_account_id:'',credit_account_id:'',reason:'',idempotency_key:uid()};error.value='';book.value=true;baseline=JSON.stringify(booking.value);state.editor={name:'Escrituração do documento',companyId:state.companyId};}
async function confirmBook(){busy.value=true;error.value='';try{const payload={version:original.value.version,reason:booking.value.reason,idempotency_key:booking.value.idempotency_key,generate_titles:booking.value.generate_titles};if(payload.generate_titles)payload.installments=booking.value.installments.map(p=>({...p,amount:amount(p.amount)}));if(booking.value.model_id)payload.model_id=booking.value.model_id;else if(booking.value.integrate){const value=(original.value.total_cents/100).toFixed(2);payload.lines=[{account_id:Number(booking.value.debit_account_id),debit:value,credit:'0.00'},{account_id:Number(booking.value.credit_account_id),debit:'0.00',credit:value}];}await api(scope(`/documents/${original.value.id}/book`,context.value.id),{method:'POST',body:payload});book.value=false;state.editor=null;changed();notify(booking.value.integrate?'Documento e lançamento contábil escriturados.':'Documento escriturado no módulo fiscal.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function closeBook(){if(busy.value)return;if(baseline!==JSON.stringify(booking.value)&&!await ask({title:'Descartar escrituração?',message:'As escolhas da escrituração ainda não foram confirmadas.',confirmLabel:'Descartar',danger:true}))return;book.value=false;state.editor=null;}
function chooseParticipant(){const p=data.value.participants.find(p=>p.id===form.value.participant_id);if(p){form.value.partner_name=p.name;form.value.partner_tax_id=p.tax_id;}}
function chooseProduct(item){const p=data.value.products.find(p=>p.id===item.master_id);if(p)Object.assign(item,{code:p.code,description:p.name,quantity:'1',unit:p.data.unit,ncm:p.data.ncm,cfop:p.data.cfop,unit_price:p.data.price,total:p.data.price});}
async function reverse(d){const reason=await ask({title:'Reverter escrituração',message:'O documento volta à conferência. Títulos sem baixa serão cancelados e a contabilidade vinculada será estornada. Baixas e conciliações devem ser desfeitas antes.',inputLabel:'Justificativa',required:true,confirmLabel:'Reverter escrituração',danger:true});if(!reason)return;try{await api(scope(`/documents/${d.id}/reverse`),{method:'POST',body:{date:periodDate(state.period),version:d.version,reason,idempotency_key:uid()}});changed();notify('Escrituração revertida com histórico preservado.');}catch(e){notify(e.message,'error');}}
const trace=ref(null);
async function showTrace(d){try{trace.value=await api(scope(`/documents/${d.id}/trace`));}catch(e){notify(e.message,'error');}}
const newItem=()=>({code:'',description:'',quantity:'1',unit_price:'0.00',total:'0.00',ncm:'',cfop:''});
onUnmounted(()=>{if(show.value||book.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">ESCRITURAÇÃO FISCAL</div><h1>Documentos fiscais</h1><p>Confira a origem, revise os dados e escolha os efeitos da escrituração.</p></div><div class="actions"><button class="button outline" v-allow="['fiscal.imports','read']" @click="navigate('imports')"><Icon name="import"/>Importar arquivos</button><button class="button primary" v-allow="['fiscal.documents','create']" @click="open()"><Icon name="plus"/>Novo documento</button></div></header><div class="summary-strip"><div><Icon name="documents"/><strong>{{data.documents.length}}</strong><span>documentos</span></div><div><span class="dot amber"></span><strong>{{data.documents.filter(d=>d.status==='pending').length}}</strong><span>pendentes</span></div><div><span class="dot green"></span><strong>{{data.documents.filter(d=>d.status==='booked').length}}</strong><span>escriturados</span></div><div class="push-right"><span>Total documental</span><strong>{{money(data.documents.reduce((s,d)=>s+d.total_cents,0))}}</strong></div></div><div v-if="loadError" class="message error">{{loadError}}</div><label class="operation-month">Competência da consulta<select v-model="monthFilter" aria-label="Competência da consulta"><option value="">Todo o exercício</option><option v-for="m in 12" :value="String(m).padStart(2,'0')">{{String(m).padStart(2,'0')}}/{{state.period.slice(0,4)}}</option></select></label><section class="panel"><div class="table-toolbar"><div class="search-field"><Icon name="search"/><input v-model="query" placeholder="Pesquisar número, participante, CFOP ou chave" aria-label="Pesquisar documentos"/></div><select v-model="direction" aria-label="Filtrar operação"><option value="">Entradas e saídas</option><option value="incoming">Entradas</option><option value="outgoing">Saídas</option></select><label>Registros por página<select v-model.number="pageSize" aria-label="Registros por página"><option :value="50">50</option><option :value="100">100</option><option :value="250">250</option><option v-for="size in [500,1000,2500,5000]" :key="size" :value="size">{{size}}</option></select></label><select v-model="status" aria-label="Filtrar estado fiscal"><option value="">Todas as situações</option><option value="pending">Pendentes</option><option value="reviewed">Conferidos</option><option value="booked">Escriturados</option></select><a v-if="!loading&&!state.contextBusy&&state.companyId&&can('fiscal.documents','read')&&can('fiscal.documents','export')" class="button outline small" :href="exportUrl" download title="Exportar todos os registros que correspondem aos filtros, incluindo outras páginas">Exportar Excel ({{filtered.length}})</a></div><BulkOperationsPanel kind="documents" :records="visible" v-model:selected-ids="selectedIds" :loading="loading" :reset-key="JSON.stringify([query,direction,status,monthFilter,page,pageSize])" @busy="bulkBusy=$event"/><div v-if="loading" class="loading-line"><Icon name="loading"/>Carregando documentos...</div><div v-else-if="filtered.length" class="table-scroll"><table><thead><tr><th>Selecionar</th><th>Operação</th><th>Documento</th><th>Participante</th><th>Escrituração</th><th>CFOP</th><th class="right">Total</th><th>Situação</th><th class="right">Ações</th></tr></thead><tbody><tr v-for="d in visible" :key="d.id"><td><input type="checkbox" :checked="selectedIds.includes(d.id)" :disabled="bulkBusy||!can('fiscal.documents','read')||(!selectedIds.includes(d.id)&&selectedIds.length>=5000)" :aria-label="`Selecionar documento ${d.number} (#${d.id})`" @change="toggleSelection(d.id,$event.target.checked)"/></td><td><span class="badge" :class="d.direction==='incoming'?'info':'neutral'"><Icon :name="d.direction==='incoming'?'in':'out'" :size="13"/>{{statusLabel(d.direction)}}</span></td><td><strong class="mono">{{d.number}}</strong><small class="cell-secondary">Mod. {{d.model}} · série {{d.series||'—'}}</small></td><td class="truncate-cell">{{d.partner_name||'Não informado'}}</td><td class="nowrap">{{date(d.posting_date)}}</td><td class="mono">{{d.cfop||'—'}}</td><td class="right money">{{money(d.total_cents)}}</td><td><span class="badge" :class="d.status==='booked'?'success':d.status==='reviewed'?'info':'warning'">{{statusLabel(d.status)}}</span><small v-if="d.import_posting?.review_pending" class="cell-secondary">Importação direta · conferir</small></td><td><div class="actions"><button class="icon-button" @click="open(d)" :aria-label="`${!canEditDocument(d)?'Ver':'Editar'} documento ${d.number}`"><Icon :name="!canEditDocument(d)?'eye':'edit'"/></button><button class="button small" @click="showTrace(d)">Origem e efeitos</button><button v-if="d.status==='booked'" class="button small" v-allow="['fiscal.documents','reverse']" @click="reverse(d)">Reverter</button><button v-if="d.status==='pending'||(d.status==='booked'&&d.import_posting?.review_pending)" class="button small" v-allow="['fiscal.documents','edit']" @click="review(d)">Conferir</button><button v-if="d.status==='reviewed'" class="button small outline" v-allow="['fiscal.documents','book']" @click="openBook(d)">Escriturar</button></div></td></tr></tbody></table></div><EmptyState v-else title="Nenhum documento neste filtro" text="Importe os arquivos de origem ou cadastre um documento manualmente." icon="documents"/><footer class="table-footer"><span>Valores informados são preservados. O sistema não presume alíquotas, créditos ou contas.</span><span>{{filtered.length}} registros · página {{page}} de {{Math.max(1,Math.ceil(filtered.length/pageSize))}}</span><div class="actions"><button class="button small" @click="page--" :disabled="page===1">Anterior</button><button class="button small" @click="page++" :disabled="page*pageSize>=filtered.length">Próxima</button></div></footer></section>
<BaseModal v-if="show" :title="locked?(original?.status==='booked'?'Documento escriturado':'Consultar documento fiscal'):original?'Editar documento fiscal':'Novo documento fiscal'" :subtitle="`${context.code} · ${context.name}`" wide @close="close"><div class="modal-tabs"><button :class="{selected:tab==='document'}" @click="tab='document'">Documento</button><button :class="{selected:tab==='items'}" @click="tab='items'">Itens e tributos</button><button :class="{selected:tab==='source'}" @click="tab='source'">Origem e conferência</button></div><div v-if="error" class="message error" role="alert">{{error}}</div><form novalidate id="document-form" @submit.prevent="save"><fieldset :disabled="locked" class="plain-fieldset"><div v-show="tab==='document'"><label v-if="original?.status==='booked'&&!locked">Motivo da alteração da escrituração *<textarea v-model="form.edit_reason" required rows="2"/></label><div class="context-notice"><Icon name="building"/><span>Escriturar em <strong>{{context.name}}</strong></span><span class="badge neutral">{{'Exercício '+context.period.slice(0,4)}}</span></div><div class="form-grid four"><label>Operação<select v-model="form.direction"><option value="incoming">Entrada</option><option value="outgoing">Saída</option></select></label><label>Modelo<select v-model="form.model"><option value="55">55 · NF-e</option><option value="65">65 · NFC-e</option><option value="57">57 · CT-e</option><option value="NFSE">NFS-e · manual</option><option value="99">Outro · manual</option></select></label><label>Número *<input v-model="form.number" required/></label><label>Série<input v-model="form.series"/></label><label>Emissão *<DateInput v-model="form.issue_date" required/></label><label>Escrituração *<DateInput v-model="form.posting_date" required/></label><label>CFOP informado<CfopInput v-model="form.cfop" aria-label="CFOP informado" :direction="form.direction" :date="form.posting_date" placeholder="0000"/></label><label>Total (R$) *<input v-model="form.total" inputmode="decimal" required placeholder="0,00"/></label><label class="span-2">Participante cadastrado<select v-model.number="form.participant_id" @change="chooseParticipant"><option :value="null">Preencher manualmente</option><option v-for="p in data.participants.filter(p=>p.active)" :value="p.id" :key="p.id">{{p.code}} · {{p.name}}</option></select></label><label class="span-2">Estabelecimento<select v-model.number="form.establishment_id"><option :value="null">Cadastro principal da empresa</option><option v-for="p in data.establishments.filter(p=>p.active)" :value="p.id" :key="p.id">{{p.code}} · {{p.name}}</option></select></label><label class="span-3">Participante *<input v-model="form.partner_name" required placeholder="Cliente, fornecedor ou prestador"/></label><label>CNPJ / CPF do participante<input v-model="form.partner_tax_id"/></label><label class="span-4">Chave do documento<input v-model="form.key" maxlength="50" placeholder="Chave de acesso, quando houver"/></label></div></div>
<div v-show="tab==='items'"><div class="section-label">Valores de tributos informados <span>Não há cálculo automático nesta tela.</span></div><div class="form-grid four"><label v-for="(label,key) in taxNames" :key="key">{{label}} (R$)<input v-if="typeof form.taxes[key]!=='object'" v-model="form.taxes[key]" inputmode="decimal" placeholder="Não informado"/><span v-else class="read-field">Detalhamento preservado na origem</span></label></div><details v-if="Object.keys(form.taxes).some(k=>!Object.hasOwn(taxNames,k))" class="source-tax-details"><summary>Valores e códigos preservados no arquivo de origem</summary><dl class="source-details"><template v-for="(v,k) in form.taxes" :key="k"><template v-if="!Object.hasOwn(taxNames,k)"><dt>{{k}}</dt><dd class="mono">{{typeof v==='object'?JSON.stringify(v):v}}</dd></template></template></dl></details><div class="section-label">Itens do documento <span>{{form.items.length}} itens</span></div><div class="table-scroll"><table class="editable-table"><thead><tr><th>Produto / serviço</th><th>Descrição</th><th>NCM</th><th>CFOP</th><th>Quantidade</th><th>Total informado</th><th></th></tr></thead><tbody><tr v-for="(item,i) in form.items" :key="i"><td><select v-model.number="item.master_id" @change="chooseProduct(item)" :aria-label="`Produto do item ${i+1}`"><option :value="null">Manual</option><option v-for="p in data.products.filter(p=>p.active)" :key="p.id" :value="p.id">{{p.code}} · {{p.name}}</option></select></td><td><input v-model="item.description" :aria-label="`Descrição do item ${i+1}`"/></td><td><input v-model="item.ncm" maxlength="8" :aria-label="`NCM do item ${i+1}`"/></td><td><CfopInput v-model="item.cfop" :direction="form.direction" :date="form.posting_date" :aria-label="`CFOP do item ${i+1}`"/></td><td><input v-model="item.quantity" :aria-label="`Quantidade do item ${i+1}`"/></td><td><input v-model="item.total" :aria-label="`Total do item ${i+1}`"/></td><td><button type="button" class="icon-button" @click="form.items.splice(i,1)" :aria-label="`Remover item ${i+1}`"><Icon name="trash" :size="14"/></button></td></tr></tbody></table></div><button v-if="!locked" type="button" class="text-button" @click="form.items.push(newItem())"><Icon name="plus" :size="16"/>Adicionar item</button></div></fieldset>
<div v-show="tab==='source'"><div class="info-card"><Icon name="filecheck"/><div><strong>{{original?.source?'Documento com origem rastreável':'Inclusão manual'}}</strong><p>{{original?.source?.file||original?.source?.filename||'Os dados informados pelo operador e as alterações ficam registrados no histórico.'}}</p></div></div><dl class="source-details"><dt>Situação</dt><dd>{{statusLabel(original?.status||'pending')}}</dd><dt>Versão</dt><dd>{{original?.version||'Novo registro'}}</dd><dt>Lançamento contábil</dt><dd>{{original?.journal_id?`Vinculado · ${original.journal_id}`:'Ainda não vinculado'}}</dd><dt>Origem / registro</dt><dd>{{original?.source?.record||original?.source?.kind||'Manual'}}</dd><dt>Conferência</dt><dd>Revise participante, operação, CFOP, itens e valores antes de escriturar.</dd></dl><div class="message warning"><Icon name="alert"/><span>O CFOP do emitente e o CFOP de escrituração da entrada podem exigir mapeamento. A importação preserva a origem e não converte o código por suposição.</span></div></div></form><template #footer><span v-if="!original" class="entry-defaults">Manter: <label><input type="checkbox" v-model="retain.date"/>Datas</label><label><input type="checkbox" v-model="retain.classification"/>Classificação</label><label><input type="checkbox" v-model="retain.partner"/>Participante</label></span><span class="footer-hint"><Icon name="shield" :size="15"/>{{locked?(original?.status==='booked'?'Documento preservado após a escrituração.':'Consulta sem permissão de alteração ou em competência bloqueada.'):original?.status==='booked'?'Salvar preserva a origem e mantém a escrituração fiscal.':'Salvar mantém o documento pendente de conferência.'}}</span><div class="actions"><button class="button" @click="close" :disabled="busy">{{locked?'Fechar':'Cancelar'}}</button><button v-if="!locked&&!original" data-save-new type="button" class="button outline" @click="submitNext" :disabled="busy">Salvar e novo · Alt+N</button><button v-if="!locked" class="button primary" aria-label="Salvar documento" form="document-form" type="submit" :disabled="busy"><Icon :name="busy?'loading':'check'"/>Salvar · Alt+S</button></div></template></BaseModal>
<BaseModal v-if="book" title="Escriturar documento" :subtitle="`${context.name} · documento ${original.number}`" @close="closeBook"><div v-if="error" class="message error" role="alert">{{error}}</div><div class="settlement-title"><strong>{{original.partner_name}}</strong><span>Total documental <b>{{money(original.total_cents)}}</b></span></div><form id="book-form" @submit.prevent="confirmBook"><label>Observação da escrituração *<input v-model="booking.reason" required placeholder="Identifique a conferência realizada"/></label><label>Modelo de contabilização revisado<select v-model.number="booking.model_id"><option value="">Definir nesta escrituração</option><option v-for="m in data.models.filter(m=>m.active&&m.data.status==='validated')" :key="m.id" :value="m.id">{{m.code}} · {{m.name}}</option></select></label><label v-if="!booking.model_id" class="choice-card"><input type="checkbox" v-model="booking.integrate" :disabled="!writable('accounting.journals')"/><div><strong>Contabilizar junto com o documento</strong><small>Informe as contas. As duas gravações serão confirmadas em conjunto.</small></div></label><div v-if="booking.integrate&&!booking.model_id" class="form-grid"><label>Conta a debitar *<select v-model.number="booking.debit_account_id" required><option value="">Selecione</option><option v-for="a in data.accounts.filter(a=>a.analytical)" :key="a.id" :value="a.id">{{a.access_code}} · {{a.name}}</option></select></label><label>Conta a creditar *<select v-model.number="booking.credit_account_id" required><option value="">Selecione</option><option v-for="a in data.accounts.filter(a=>a.analytical)" :key="a.id" :value="a.id">{{a.access_code}} · {{a.name}}</option></select></label></div><label class="choice-card"><input v-model="booking.generate_titles" :disabled="!writable('financial.titles')" type="checkbox"/><div><strong>Gerar títulos financeiros vinculados</strong><small>Confira parcelas e vencimentos. Todas as gravações são confirmadas juntas.</small></div></label><template v-if="booking.generate_titles"><button v-if="original.invoices?.length" type="button" class="button small" @click="booking.installments=original.invoices.flatMap(p=>p.installments||[p]).map(p=>({due_date:p.due_date,amount:p.amount}))">Usar parcelas da origem</button><InstallmentsEditor v-model="booking.installments" :total="original.total_cents" :date="original.issue_date"/></template><div class="message subtle"><Icon name="info"/><span>Esta ação registra os dados conferidos. Não recalcula tributos nem substitui a validação fiscal.</span></div></form><template #footer><button class="button" @click="closeBook" :disabled="busy">Cancelar</button><button class="button primary" form="book-form" type="submit" :disabled="busy"><Icon :name="busy?'loading':'check'"/>Confirmar escrituração</button></template></BaseModal><BaseModal v-if="trace" title="Origem e efeitos do documento" wide @close="trace=null"><p>Documento {{trace.document.number}} · {{trace.document.partner_name}}</p><div class="section-label">Títulos financeiros</div><table><thead><tr><th>Título</th><th>Vencimento</th><th>Valor</th><th>Saldo</th><th>Situação</th></tr></thead><tbody><tr v-for="t in trace.titles" :key="t.id"><td>#{{t.id}} {{t.description}}</td><td>{{date(t.due_date)}}</td><td>{{money(t.amount_cents)}}</td><td>{{money(t.balance_cents)}}</td><td>{{statusLabel(t.status)}}</td></tr></tbody></table><div class="section-label">Lançamentos vinculados</div><p v-for="j in trace.journals" :key="j.id">#{{j.id}} · <template v-if="j.deleted">Lançamento excluído fisicamente; referência histórica preservada.</template><template v-else>{{date(j.date)}} · {{j.history}} · {{money(j.total_cents)}} · {{statusLabel(j.status)}}</template></p><div class="section-label">Histórico de operações</div><p v-for="e in trace.events" :key="e.id">{{e.created_at}} · {{e.actor}} · {{e.action}} · {{e.details.reason||''}}</p><template #footer><button class="button" @click="trace=null">Fechar</button></template></BaseModal></div></template>
